import{_ as a,o as t,c as o,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"テンプレートのインポートとプロファイルの管理","description":"","frontmatter":{"title":"テンプレートのインポートとプロファイルの管理","docId":"user.automations.templates","translationKey":"user.automations.templates","locale":"ja","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"e9847c93a8a75fd5a58cd115b49b8e0bcb091ceda1dbdf2c226b52667eb17e23","translationRevision":"bb935b9e554f85730342832841cff07c20b62e331eebe76cd184628493d84164","order":50},"headers":[],"relativePath":"ja/user/automations/templates.md","filePath":"ja/user/automations/templates.md","lastUpdated":1794611623000}'),i={name:"ja/user/automations/templates.md"};function l(s,e,d,n,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="import-templates-and-manage-profiles" tabindex="-1">テンプレートのインポートとプロファイルの管理 <a class="header-anchor" href="#import-templates-and-manage-profiles" aria-label="Permalink to &quot;テンプレートのインポートとプロファイルの管理 {#import-templates-and-manage-profiles}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>確認済みのルールやルール集を、誤って実行せずに再利用します。<strong>自動化</strong>、信頼できる JSON ファイルまたはカタログ項目、アクションが必要とするプラグインを用意します。既存の構成を置き換える前に、現在のプロファイルをエクスポートしてください。</p><h2 id="choose-the-right-surface" tabindex="-1">適切な操作画面を選ぶ <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to &quot;適切な操作画面を選ぶ {#choose-the-right-surface}&quot;">​</a></h2><p><code>.tiktemplate.json</code> は1つのイベントとそのアクションを記述し、<code>.tikprofile.json</code> は複数のテンプレートをまとめます。組み込み・カスタムテンプレート、Cloud ライブラリ、手動テンプレートインポートは自動化のテンプレートダイアログで開きます。プロファイルの作成、選択、エクスポート、手動インポートはプロファイルツールバーを使います。<strong>プラグイン → 探す</strong> はプラグインを探す画面で、テンプレートとプロファイルはこちらで扱います。</p><h2 id="review-and-import" tabindex="-1">確認してインポートする <a class="header-anchor" href="#review-and-import" aria-label="Permalink to &quot;確認してインポートする {#review-and-import}&quot;">​</a></h2><ol><li>対象のインポートダイアログを開き、ファイルを選ぶか、対応する JSON を貼り付けます。続行前に準備された名前と出所を確認します。</li><li>テンプレートではトリガー、アクション種別、パラメーターを確認します。プロファイルでは項目数と共通パラメーターも確認します。</li><li>例の送信先、メディアパス、視聴者識別子を自分の構成に合う値に置き換えます。共有用ファイルに認証情報を貼り付けないでください。</li><li>適用・インポートを明示的に実行して結果を待ちます。定義が無効とは限りません。レビューの enabled 値を確認します。後で選択し、各アクションとイベントを確認して必要なものだけを明示的に有効化します。</li><li>まずログだけのテストをするか、定義を確認します。HTTP、音声、ポイント、プラグインのテストでは実際の処理が動きます。</li><li>確定前に移動先メンバーの有効化とその他の無効化を確認します。単独レコードや以前無効にした移動先も対象です。効果は trigger・条件が必要で、Cloud sync ではありません。</li></ol><p><code>{{ params.giftName }}</code> などのパラメーターはテンプレート適用時に解決されます。<code>{{ event.user.uniqueId }}</code> などの実行時参照は各イベントのために残り、<a href="./variables.html">グローバル変数</a> は実行時に保存済みの共有値を提供します。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>ローカルのテンプレート・プロファイルの入出力を利用できます。Cloud の閲覧には対応するホスト機能とアカウント・サービスが必要です。カタログのプレビューだけでは外部サービスの動作は確認できません。必要なプラグインがなければ、インストールと設定が済むまで取り込んだ定義を使えない場合があります。</p><h2 id="recovery" tabindex="-1">問題が起きたとき <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;問題が起きたとき {#recovery}&quot;">​</a></h2><p>無効な JSON はパーサーのエラーと期待される文書形式を確認します。任意の JSON の名前を変えても形式は変換されません。リビジョン競合では保存済みライブラリを更新してから再適用します。正常なプロファイルの書き出しを保持し、含まれないデータについては<a href="./../preferences/backups.html">バックアップ</a> を参照してください。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>手動テンプレート import はまずカタログ文書を保存し、適用で関連アクション・イベントを作ります。<code>enabled</code> 省略時の parser 既定は true で、適用も値を保持します。手動プロファイル import も項目を所有者レビューへ渡します。Cloud カタログはテンプレートを保存し、Cloud プロファイルは来歴付き変更を準備します。出所・プレビュー成功だけで一律無効とは保証できません。最終比較と保存状態を確認します。CLI では明示的に <code>tiktools template import file.tiktemplate.json --disabled</code> または <code>tiktools template profile-import file.tikprofile.json --disabled</code> を使います。</p><p>プロファイル切り替えは有効状態を変えます。確定すると移動先の全メンバーを有効化し、その他すべてのアクション・イベント（単独項目を含む）を無効化します。以前無効にした移動先メンバーも有効になる場合があります。両方のリストを確認します。副作用にはトリガー・条件・利用可能 runtime が必要で、切り替え自体は Cloud 同期を送りません。</p>',15)])])}const h=a(i,[["render",l]]);export{m as __pageData,h as default};
